draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30 + 20 * Math.sin(t), H/2 + 70);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30 - 20 * Math.sin(t), H/2 + 70);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 - 20 + 10 * Math.sin(t), H/2 + 130);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 + 20 - 10 * Math.sin(t), H/2 + 130);
  ctx.stroke();

  // holding a fishing rod
  ctx.beginPath();
  ctx.moveTo(W/2 - 30 + 20 * Math.sin(t), H/2 + 70);
  ctx.lineTo(W/2 - 80 + 20 * Math.sin(t), H/2 - 30);
  ctx.stroke();

  // fishing rod tip
  ctx.beginPath();
  ctx.arc(W/2 - 80 + 20 * Math.sin(t), H/2 - 30, 5, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
